mapper.select:
SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM quests
WHERE battle_id = #{battleId}
  AND user_id = #{userId}

SELECT COUNT(1)
FROM quests
WHERE battle_id = #{battleId}

SELECT guild_id
FROM boss_battles
WHERE battle_id = #{battleId}

SELECT role
FROM guild_members
WHERE guild_id = #{guildId}
  AND user_id = #{userId}
  AND left_at IS NULL
LIMIT 1

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM quest_verifications
WHERE quest_id = #{questId}

SELECT COUNT(1)
FROM (
    SELECT dns.user_id, dns.summary_date
    FROM daily_nutrition_summaries dns
    JOIN guild_members gm ON gm.user_id = dns.user_id
    JOIN users u ON u.user_id = gm.user_id
    WHERE gm.guild_id = #{guildId}
      AND gm.left_at IS NULL
      AND u.status = 'ACTIVE'
      AND dns.summary_date BETWEEN #{startDate} AND #{endDate}
      AND dns.total_sugar_g <= #{thresholdValue}
    GROUP BY dns.user_id, dns.summary_date
) counted

SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM reward_claims
WHERE user_id = #{userId}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}
